def inline(x):
 x=esc(x);x=re.sub(r'`([^`]+)`',r'<code>\1</code>',x);x=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',x);x=re.sub(r'\[([^\]]+)\]\((https://[^)]+)\)',r'<a href="\2" target="_blank" rel="noopener">\1</a>',x);return x
